export type AddAthleteSource = "FRIENDS" | "CLUB" | "DIRECT";

export interface AddAthleteCandidate {
  userId: string;
  displayName: string;
  avatarUrl: string | null;
  source: "FRIENDS" | "CLUB";
}

export interface AddAthleteCandidatesResponse {
  rows: AddAthleteCandidate[];
  nextCursor: string | null;
}

export type AddAthletePlayerInput =
  | { userId: string; role?: "MAIN" | "PARTNER" }
  | { displayName: string; email?: string; phone?: string; role?: "MAIN" | "PARTNER" };

export interface AddAthletesRequest {
  source: AddAthleteSource;
  divisionId?: string;
  teamName?: string;
  players: AddAthletePlayerInput[];
  organizerNote?: string;
}

export interface AddAthletesResponse {
  participant: TournamentParticipant;
  entryFeeAtRegistration?: number | null;
  organizerNote?: string | null;
  isPresent?: boolean | null;
  claim?: { status?: string; claimToken?: string | null } | null;
}
…
export const tournamentsApi = {
  getAddAthleteCandidates: (id: string, params: {
    source: "FRIENDS" | "CLUB";
    divisionId?: string;
    search?: string;
    cursor?: string;
    limit?: number;
  }) =>
    api.get<ApiResponse<AddAthleteCandidatesResponse>>(
      `/tournaments/${id}/add-athletes/candidates`,
      { params },
    ),
  addAthletes: (id: string, data: AddAthletesRequest) =>
    api.post<ApiResponse<AddAthletesResponse>>(`/tournaments/${id}/add-athletes`, data),
  getFeesConfig: () =>
    api.get<ApiResponse<TournamentFeesConfig>>("/tournaments/fees"),
  getTournaments: (params?: Record<string, unknown>) =>
    api.get<PaginatedTournaments>("/tournaments", { params }),
  getPublicTournaments: (params?: Record<string, unknown>) =>
    api.get<PaginatedTournaments>("/tournaments/public", { params }),
  getMyTournaments: () => api.get<ApiResponse<Tournament[]>>("/tournaments/my"),
  getMyManagementTournaments: (params?: {
    cursor?: string;
    limit?: number;
    offset?: number;
    status?: "COMPLETED";
  }) =>
    api.get<ApiResponse<OrganizerTournamentListItem[]>>(
      "/tournaments/my/management",
      { params },
    ),
  getMyWorkspace: (params?: { includeRefereeMatches?: boolean }) =>
    api.get<ApiResponse<TournamentWorkspace>>("/tournaments/workspace/me", {
      params,
    }),
  getTournamentById: (id: string, params?: Record<string, unknown>) =>
    api.get<ApiResponse<Tournament>>(`/tournaments/${id}`, { params }),
  getTournamentVenues: (id: string) =>
    api.get<ApiResponse<TournamentVenueWithCourts[]>>(
      `/tournaments/${id}/venues`,
    ),
  createTournamentVenue: (
    id: string,
    data: {
      name: string;
      locationAddress: string;
      venueId?: string;
      isDefault?: boolean;
      initialCourtCount?: number;
      courtPrefix?: string;
    },
  ) =>
    api.post<ApiResponse<TournamentVenueWithCourts>>(
      `/tournaments/${id}/venues`,
      data,
    ),
  updateTournamentVenue: (
    id: string,
    venueId: string,
    data: { name?: string; locationAddress?: string },
  ) =>
    api.patch<ApiResponse<TournamentVenueWithCourts>>(
      `/tournaments/${id}/venues/${venueId}`,
      data,
    ),
  setDefaultTournamentVenue: (id: string, venueId: string) =>
    api.patch<ApiResponse<{ success: boolean; defaultVenueId: string }>>(
      `/tournaments/${id}/venues/${venueId}/default`,
    ),
  deleteTournamentVenue: (id: string, venueId: string) =>
    api.delete<
      ApiResponse<{
        success: boolean;
        remainingVenueIds: string[];
        defaultVenueId: string | null;
      }>
    >(`/tournaments/${id}/venues/${venueId}`),
  addVenueCourtDirect: (
    id: string,
    venueId: string,
