import { create } from 'zustand';
import { persist } from 'zustand/middleware';

export interface User {
  id: string;
  email: string;
  fullName: string;
  avatarUrl?: string | null;
  coverUrl?: string | null;
  roles: string[];
  role?: string;
  phoneNumber?: string | null;
  dateOfBirth?: string | null;
  gender?: string | null;
  address?: string | null;
  bio?: string | null;
  createdAt?: string | null;
  provinceCode?: string | null;
  isEmailVerified?: boolean;
  isPhoneVerified?: boolean;
  isVerified?: boolean;
  isGenderLocked?: boolean;
  allowStrangerMessages?: boolean;
  bankName?: string | null;
  bankAccountNumber?: string | null;
  bankAccountName?: string | null;
}

interface AuthState {
  user: User | null;
  isAuthenticated: boolean;
  hasHydrated: boolean;
  isSessionReady: boolean;
  // True only while a session validation is genuinely in flight. It separates
  // "not validated yet" from "validated and the session is not usable", which
  // `isSessionReady === false` alone cannot express. Transient by design: never
  // persisted, so a reload can never resurrect a stale pending frame.
  isSessionValidationPending: boolean;
  // Id of the newest session validation. A request carries the id it was
  // started with and may only act on the session while it is still the newest
  // one, so an answer that outlives a logout or a newer bootstrap is dropped
  // instead of restoring a session nobody owns. Transient for the same reason
  // the pending flag is: a rehydrated store has never issued a request.
  sessionValidationId: number;
  // Which sign-in the data on the wire belongs to. It advances on a sign-out and
  // on a new or different identity, and deliberately not when a validation
  // merely restarts: reads that are already in flight for this session must
  // keep sharing, while anything issued after a new sign-in must not be able
  // to pick up the previous session's answer. Transient like the id above, so
  // it is never persisted with the identity it describes.
  authSessionGeneration: number;
  setUser: (user: User) => void;
  setHasHydrated: (value: boolean) => void;
  setSessionReady: (value: boolean) => void;
  setSessionValidationPending: (value: boolean) => void;
  startSessionValidation: () => number;
  isSessionValidationOwner: (id: number) => boolean;
  finishSessionValidation: (id: number) => void;
  logout: () => void;
}

export const useAuthStore = create<AuthState>()(
  persist(
    (set, get) => ({ … }),
    { … }
  )
);

