export async function fulfillApi(route: Route, payload: unknown, status = 200) {
…
  await route.fulfill({ status, headers, json: payload });
}

export async function openManage(
  page: Page,
  options: {
    divisions?: Array<typeof divisionFixture>;
    tab?: string;
    matchType?: 'SINGLES' | 'DOUBLES';
    withBracket?: boolean;
  } = {},
) {
  const matchType = options.matchType ?? 'SINGLES';
  const divisions = options.divisions ?? [{ ...divisionFixture, matchType }];
  const withBracket = options.withBracket ?? false;
  const currentTournament = { ...tournament, matchType };

  await page.addInitScript((user) => {
    localStorage.setItem('auth-storage', JSON.stringify({
      state: { user, isAuthenticated: true },
      version: 0,
    }));
  }, organizer);

  await page.route('**/api/v1/**', async (route) => {
    const pathname = new URL(route.request().url()).pathname;

    if (pathname.endsWith('/users/profile')) {
      await fulfillApi(route, { data: organizer });
      return;
    }
    if (pathname === `/api/v1/tournaments/${tournamentId}`) {
      await fulfillApi(route, { data: currentTournament });
      return;
    }
    if (pathname === `/api/v1/tournaments/${tournamentId}/divisions`) {
      await fulfillApi(route, { data: divisions });
      return;
    }
    if (pathname === `/api/v1/tournaments/${tournamentId}/bracket`) {
      await fulfillApi(route, { data: withBracket ? bracketFixture : { stages: [] } });
      return;
    }
    if (pathname === `/api/v1/tournaments/${tournamentId}/manage/participants`) {
      await fulfillApi(route, { data: divisions.length === 0 ? [] : [participant] });
      return;
    }

    await fulfillApi(route, { data: [] });
  });

  const tab = options.tab ? `?tab=${options.tab}` : '';
  await page.goto(`/organizer/tournaments/${tournamentId}/manage${tab}`, { waitUntil: 'domcontentloaded' });
}

