        ) : state === 'success' ? (
          <div className="text-center"><CheckCircle aria-hidden="true" className="mx-auto h-9 w-9 text-emerald-600" /><h1 className="mt-4 text-xl font-bold">{t('successTitle')}</h1><p className="mt-2 text-sm text-slate-600">{t('successDescription')}</p><Button type="button" className="mt-6 min-h-11" onClick={() => router.push(`/tournaments/${id}`)}>{t('viewTournament')}</Button></div>
        ) : state === 'error' ? (
          <div className="text-center"><AlertTriangle aria-hidden="true" className="mx-auto h-9 w-9 text-amber-600" /><h1 className="mt-4 text-xl font-bold">{t('invalidTitle')}</h1><p role="alert" className="mt-2 text-sm text-slate-600">{user && !user.isEmailVerified ? t('verificationRequired') : t('invalidDescription')}</p>{user && !user.isEmailVerified && <Button type="button" variant="outline" className="mt-5 min-h-11" onClick={() => window.location.reload()}>{t('retryAfterVerification')}</Button>}</div>
        ) : state === 'missing' ? (
          <div className="text-center"><AlertTriangle aria-hidden="true" className="mx-auto h-9 w-9 text-amber-600" /><h1 className="mt-4 text-xl font-bold">{t('invalidTitle')}</h1><p role="alert" className="mt-2 text-sm text-slate-600">{t('invalidDescription')}</p></div>
        ) : !hasHydrated || !isSessionReady || isSessionValidationPending ? (
          <div role="status" className="text-center"><Loader2 aria-hidden="true" className="mx-auto h-8 w-8 animate-spin text-blue-600" /><p className="mt-4 text-sm text-slate-600">{t('loading')}</p></div>
        ) : !isAuthenticated ? (
          <div className="text-center"><h1 className="text-xl font-bold">{t('loginTitle')}</h1><p className="mt-2 text-sm text-slate-600">{t('loginDescription')}</p><p className="mt-2 text-sm text-slate-600">{t('fragmentReminder')}</p><Link href={loginHref} target="_blank" rel="noopener noreferrer" className="mt-5 inline-flex min-h-11 items-center justify-center rounded-md bg-blue-700 px-4 py-2 text-sm font-semibold text-white hover:bg-blue-800">{t('login')}</Link></div>
        ) : null}
      </section>
    </main>
  );
}

