    const url = new URL(route.request().url());
    queries.push(url);
    await fulfillApi(route, url.searchParams.get('cursor')
      ? { data: { rows: [], nextCursor: null } }
      : { data: { rows: [{ userId: 'friend-1', displayName: 'Friend Athlete', avatarUrl: null, source: 'FRIENDS' }], nextCursor: 'page-2' } });
  });
  await openManage(page, { tab: 'registration' });
  await page.getByRole('button', { name: 'Thêm VĐV' }).click();
  const dialog = page.getByRole('dialog', { name: 'Thêm VĐV' });
  await dialog.getByRole('button', { name: 'Bạn bè' }).click();
  await dialog.getByLabel('Tìm VĐV').fill('Friend');
  await expect(dialog.getByText('Friend Athlete')).toBeVisible();
  await expect(dialog.getByText(/@|09\d{8}/)).toHaveCount(0);
  await dialog.getByRole('button', { name: 'Trang tiếp' }).click();
  await expect.poll(() => queries.some((url) => url.searchParams.get('cursor') === 'page-2')).toBe(true);
  expect(queries[0].searchParams.get('source')).toBe('FRIENDS');
});

test('player claims a guest roster with the URL fragment and the fragment is removed', async ({ page }) => {
  let claimRequest: Record<string, unknown> | undefined;
  await page.route(`**/api/v1/tournaments/${tournamentId}/guest-rosters/guest-1/claim`, async (route) => {
    claimRequest = route.request().postDataJSON();
    await fulfillApi(route, { data: { success: true } });
  });
  await openManage(page);
  await page.goto(`/tournaments/${tournamentId}/guest-claim/guest-1#claimToken=one-time-secret`, { waitUntil: 'domcontentloaded' });

  await expect(page.getByRole('heading', { name: 'Đã nhận vị trí thi đấu' })).toBeVisible();
  await expect.poll(() => claimRequest).toEqual({ claimToken: 'one-time-secret' });
  expect(new URL(page.url()).hash).toBe('');
  expect(new URL(page.url()).search).not.toContain('one-time-secret');
});

