          <Button type="button" variant="outline" onClick={() => onOpenChange(false)} disabled={submitting}>{t('cancel')}</Button>
          <Button type="button" onClick={() => void submit()} disabled={!canSubmit || submitting || !divisionId} aria-busy={submitting} className="min-h-11">
            {submitting ? <Loader2 aria-hidden="true" className="mr-2 h-4 w-4 animate-spin" /> : <UserPlus aria-hidden="true" className="mr-2 h-4 w-4" />}
            {submitting ? t('submitting') : t('submit')}
          </Button>
        </ModalFooter>
      </ModalContent>
    </Modal>
  );
