'use client';

import { use, useEffect, useRef, useState } from 'react';
import { useTranslations } from 'next-intl';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { AlertTriangle, CheckCircle, Loader2 } from 'lucide-react';
import { Button } from '@/components/ui/Button';
import { tournamentsApi } from '@/features/tournaments/api';
import { useAuthStore } from '@/lib/zustand/authStore';

type ClaimState = 'waiting' | 'claiming' | 'success' | 'error' | 'missing';
export default function GuestRosterClaimPage({ params }: { params: Promise<{ id: string; guestId: string }> }) {
  const { id, guestId } = use(params);
  const t = useTranslations('GuestClaim');
  const router = useRouter();
  const { user, isAuthenticated, hasHydrated, isSessionReady, isSessionValidationPending } = useAuthStore();
  const [claimToken, setClaimToken] = useState('');
  const [state, setState] = useState<ClaimState>('waiting');
  const attempted = useRef(false);

  useEffect(() => {
    const fragment = window.location.hash.slice(1);
    const token = new URLSearchParams(fragment).get('claimToken') || '';
    setClaimToken(token);
    if (!token) setState('missing');
  }, []);

  useEffect(() => {
    if (!claimToken || attempted.current || !hasHydrated || !isSessionReady || isSessionValidationPending) return;
    if (!isAuthenticated || !user) return;
    if (!user.isEmailVerified) {
      setState('error');
      return;
    }

    attempted.current = true;
    window.history.replaceState(window.history.state, '', `${window.location.pathname}${window.location.search}`);
    setState('claiming');
    void tournamentsApi.claimGuestRoster(id, guestId, { claimToken }).then(() => {
      setState('success');
      setClaimToken('');
    }).catch(() => {
      // Use one neutral message for expired, reused, malformed, and email-mismatch claims.
      setState('error');
      setClaimToken('');
    });
  }, [claimToken, guestId, hasHydrated, id, isAuthenticated, isSessionReady, isSessionValidationPending, user]);

  const loginHref = `/login?redirect=${encodeURIComponent(`/tournaments/${id}/guest-claim/${guestId}`)}`;

  return (
    <main className="mx-auto flex min-h-[70vh] max-w-xl items-center px-4 py-10">
      <section className="w-full rounded-2xl border border-slate-200 bg-white p-6 shadow-sm sm:p-8" aria-live="polite">
        {state === 'claiming' ? (
          <div className="text-center"><Loader2 aria-hidden="true" className="mx-auto h-8 w-8 animate-spin text-blue-600" /><h1 className="mt-4 text-xl font-bold">{t('processing')}</h1></div>
        ) : state === 'success' ? (
          <div className="text-center"><CheckCircle aria-hidden="true" className="mx-auto h-9 w-9 text-emerald-600" /><h1 className="mt-4 text-xl font-bold">{t('successTitle')}</h1><p className="mt-2 text-sm text-slate-600">{t('successDescription')}</p><Button type="button" className="mt-6 min-h-11" onClick={() => router.push(`/tournaments/${id}`)}>{t('viewTournament')}</Button></div>
        ) : state === 'error' ? (
          <div className="text-center"><AlertTriangle aria-hidden="true" className="mx-auto h-9 w-9 text-amber-600" /><h1 className="mt-4 text-xl font-bold">{t('invalidTitle')}</h1><p role="alert" className="mt-2 text-sm text-slate-600">{user && !user.isEmailVerified ? t('verificationRequired') : t('invalidDescription')}</p>{user && !user.isEmailVerified && <Button type="button" variant="outline" className="mt-5 min-h-11" onClick={() => window.location.reload()}>{t('retryAfterVerification')}</Button>}</div>
        ) : state === 'missing' ? (
          <div className="text-center"><AlertTriangle aria-hidden="true" className="mx-auto h-9 w-9 text-amber-600" /><h1 className="mt-4 text-xl font-bold">{t('invalidTitle')}</h1><p role="alert" className="mt-2 text-sm text-slate-600">{t('invalidDescription')}</p></div>
        ) : !hasHydrated || !isSessionReady || isSessionValidationPending ? (
          <div role="status" className="text-center"><Loader2 aria-hidden="true" className="mx-auto h-8 w-8 animate-spin text-blue-600" /><p className="mt-4 text-sm text-slate-600">{t('loading')}</p></div>
        ) : !isAuthenticated ? (
          <div className="text-center"><h1 className="text-xl font-bold">{t('loginTitle')}</h1><p className="mt-2 text-sm text-slate-600">{t('loginDescription')}</p><p className="mt-2 text-sm text-slate-600">{t('fragmentReminder')}</p><Link href={loginHref} target="_blank" rel="noopener noreferrer" className="mt-5 inline-flex min-h-11 items-center justify-center rounded-md bg-blue-700 px-4 py-2 text-sm font-semibold text-white hover:bg-blue-800">{t('login')}</Link></div>
        ) : null}
      </section>
    </main>
  );
}

